{id:"csv_fainting_example",family:"anatomy_insert",tags:["fainting","syncope","blood","brain","vessel","oxygen"],text:"CSV example, Strangest Things Your Body Does scene 105 (09:18-09:27): yellow background with head/brain/vessels for blood flow; 'Fainting (Syncope)' is overlay metadata."}
];
const ranked=chunks.map(chunk=>({chunk,score:tokens.reduce((n,t)=>n+(chunk.tags.some(tag=>tag===t||tag.includes(t)||t.includes(tag))?2:0),0)+(queryText.includes(chunk.family)?6:0)}));
const selected=ranked.filter(x=>x.chunk.family==="shared").map(x=>x.chunk);
const matches=ranked.filter(x=>x.chunk.family!=="shared").sort((a,b)=>b.score-a.score).filter(x=>x.score>0).slice(0,3).map(x=>x.chunk);
selected.push(...matches);
if(!matches.length)selected.push(chunks.find(x=>x.id==="character_environment"));
return "Retrieved from fred-style-v2-csv. These are text rules and selected CSV examples, not Drive image files. Apply only relevant families; preserve timing, overlays, and editor cues separately.\\n\\n"+selected.map(c=>"["+c.id+" | "+c.family+"]\\n"+c.text).join("\\n\\n");
})();
return "FRED_VISUAL_ANCHORS_V3: actual approved Drive images override generic character assumptions. Casual character: brown skin, dark green shirt, oversized rounded head, white narrow eyes, tiny pupils, very thin black limbs. Background: yellow walls, green sofa, blue accents, rough black ink perspective, flat fills. Preserve the correct identity; the casual man is distinct from the cream-faced professor host.\n\n" + previousBrief;

